+// cloneDefaultFlag returns a per-command copy of a package-level default flag
+// (HelpFlag, VersionFlag) so concurrently run commands don't share parse state.
+func cloneDefaultFlag(f Flag) Flag {
+	bf, ok := f.(*BoolFlag)
+	if !ok {
+		return f
+	}
+	c := *bf
+	c.applied = false
+	c.hasBeenSet = false
+	c.count = 0
+	c.value = nil
+	return &c
+}
+
+func (cmd *Command) setDefaultFlag(slot *Flag, global Flag) {
+	if hasFlag(cmd.Flags, global) {
+		return
+	}
+	fl := cloneDefaultFlag(global)
+	if *slot != nil {
+		if i := slices.Index(cmd.Flags, *slot); i >= 0 {
+			cmd.Flags[i] = fl
+			*slot = fl
+			return
+		}
+	}
+	cmd.appendFlag(fl)
+	*slot = fl
+}
