+func TestCommand_RunConcurrently(t *testing.T) {
+	type result struct {
+		index      int
+		ran        bool
+		err        error
+		panicValue any
+	}
+
+	const commandCount = 100
+	results := make(chan result, commandCount)
+	var wg sync.WaitGroup
+	wg.Add(commandCount)
+
+	for i := 0; i < commandCount; i++ {
+		go func(i int) {
+			defer wg.Done()
+
+			var ran bool
+			res := result{index: i}
+			defer func() {
+				if p := recover(); p != nil {
+					res.panicValue = p
+				}
+				res.ran = ran
+				results <- res
+			}()
+
+			cmd := &Command{
+				Name:      "app",
+				Version:   "1.0",
+				Writer:    io.Discard,
+				ErrWriter: io.Discard,
+				Action: func(context.Context, *Command) error {
+					ran = true
+					return nil
+				},
+			}
+			args := []string{"app"}
+			if i%2 == 0 {
+				args = append(args, "--help")
+			}
+			res.err = cmd.Run(context.Background(), args)
+		}(i)
+	}
+
+	wg.Wait()
+	close(results)
+
+	for res := range results {
+		assert.Nil(t, res.panicValue, "run %d panicked: %v", res.index, res.panicValue)
+		assert.NoError(t, res.err, "run %d", res.index)
+		assert.Equal(t, res.index%2 != 0, res.ran, "run %d", res.index)
+	}
+}
+
+func TestCommand_RunTwiceDoesNotDuplicateHelpFlag(t *testing.T) {
+	subRan := false
+	sub := &Command{
+		Name:   "sub",
+		Action: func(context.Context, *Command) error { subRan = true; return nil },
+	}
+	cmd := &Command{
+		Name:      "app",
+		Writer:    io.Discard,
+		ErrWriter: io.Discard,
+		Commands:  []*Command{sub},
+	}
+
+	require.NoError(t, cmd.Run(context.Background(), []string{"app", "sub", "--help"}))
+	assert.False(t, subRan)
+	require.NoError(t, cmd.Run(context.Background(), []string{"app", "sub"}))
+	assert.True(t, subRan)
+
+	for _, c := range []*Command{cmd, sub} {
+		helpFlagCount := 0
+		for _, fl := range c.Flags {
+			if slices.Contains(fl.Names(), "help") {
+				helpFlagCount++
+			}
+		}
+		assert.Equal(t, 1, helpFlagCount, "command %q", c.Name)
+	}
+
+	assert.False(t, HelpFlag.IsSet())
+	assert.Nil(t, HelpFlag.(*BoolFlag).value)
+}
